import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Interaktive Widgets","description":"Universal, Radialregler und Inventwo-Vergleich ab Studio 0.1.295.","frontmatter":{"title":"Interaktive Widgets","description":"Universal, Radialregler und Inventwo-Vergleich ab Studio 0.1.295."},"headers":[],"relativePath":"projects/grafik-visual-studio/interaktiv.md","filePath":"projects/grafik-visual-studio/interaktiv.md","lastUpdated":1792857501000}'),a={name:"projects/grafik-visual-studio/interaktiv.md"};function s(d,e,l,o,u,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="interaktive-widgets" tabindex="-1">Interaktive Widgets <a class="header-anchor" href="#interaktive-widgets" aria-label="Permalink to &quot;Interaktive Widgets&quot;">​</a></h1><p><strong>Studio 0.1.295</strong> ergänzt die wichtigsten Funktionsgruppen aus dem <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/inventwo-interactive-audit-2026-10-12.md" target="_blank" rel="noreferrer">Inventwo-VIS-2-Vergleich</a>. <a href="/en/projects/grafik-visual-studio/interaktiv">English</a> · <a href="/fr/projects/grafik-visual-studio/interaktiv">Français</a>.</p><h2 id="universal" tabindex="-1">Universal <a class="header-anchor" href="#universal" aria-label="Permalink to &quot;Universal&quot;">​</a></h2><p>Neben Schalten und dem bisherigen Zustandzyklus gibt es feste Tastwerte, Haltewerte mit Wiederherstellung des vorherigen Werts, Erhöhen/Verringern mit Grenzen, Navigation auf Studio-Seiten, konfigurierbare Dialogansichten und HTTP-Aufrufe. Alte Taster behalten den Zyklusmodus, bis ausdrücklich eine neue Option gewählt wird. Eigenschaftsgruppen und gespeicherte Einstellungen bleiben erhalten.</p><p>Im Standardzustand oder einem einzelnen Zustand lassen sich außerdem <strong>Eingebettete Ansicht</strong>, <strong>Farbwähler</strong> und <strong>Analoguhr</strong> auswählen. Ansichten können eingepasst werden; rekursive Einbettungen werden verhindert. Der Farbwähler bietet Farbfläche/Farbkreis, HSV-/RGB-Regler und optional Alpha/Kelvin. HEX, HEX8, RGB, HSL, HSV und CIE-xy gehen an einen Texthelfer; HA-Lichter erhalten geprüfte RGB-/Kelvin-Befehle. Alpha betrifft HEX8, nicht den RGB-Befehl. Die Analoguhr nutzt die Browserzeit mit optionalen Ziffern/Sekunden und einstellbaren Farben.</p><p><strong>Interaktiv-Sprache</strong> wählt DE/EN/FR für Universal und Radialregler unabhängig von der Oberfläche. Eigene Texte, Entitäts-/Seitennamen und technische Werte werden nicht übersetzt.</p><h2 id="radialregler-und-vorschaubilder" tabindex="-1">Radialregler und Vorschaubilder <a class="header-anchor" href="#radialregler-und-vorschaubilder" aria-label="Permalink to &quot;Radialregler und Vorschaubilder&quot;">​</a></h2><p>Spur, aktive Spur und Daumen unterstützen CSS-Farben und <code>linear-gradient(90deg, red, rgb(255,200,0) 50%, green)</code>. Prozentpositionen und Richtungen wie <code>to top</code> funktionieren; Stilübernahme bleibt gültig. Bestehende einfache Farben ändern sich nicht.</p><p>Interaktiv-Vorschauen füllen seit 0.1.294 den Rahmen. Ab 0.1.295 werden auch Material-Design-Icons samt Symbolbereich größer angezeigt, in Seitenleiste und Widget-Auswahl. Dafür genügt das Studio-Update.</p><h2 id="verhalten-und-grenzen" tabindex="-1">Verhalten und Grenzen <a class="header-anchor" href="#verhalten-und-grenzen" aria-label="Permalink to &quot;Verhalten und Grenzen&quot;">​</a></h2><p>HTTP GET läuft im Browser mit 15 Sekunden Timeout, ohne Studio-Anmeldedaten und ohne Serverproxy. CORS und Mixed-Content-Regeln gelten. Die Navigations-PIN ist nur eine Bedienungshürde im Projekt, keine Zugriffsberechtigung. Bei Browserabsturz oder Netzverlust kann ein Haltewert nicht zuverlässig zurückgestellt werden; kritische Verbraucher brauchen einen HA-seitigen Timeout.</p><p>Studio verwendet HA-Entitäten und Projektseiten. Separat frei gebundene ioBroker-Farbkomponenten und sämtliche Inventwo-Uhrdetails sind nicht nachgebildet; eine vollständige 1:1-Pixelgleichheit wird nicht behauptet. Die Gesamtoberfläche bleibt DE/EN. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/universal-0.1.295.md" target="_blank" rel="noreferrer">Ausführliche Anleitung DE/EN/FR</a>.</p>',12)])])}const b=n(a,[["render",s]]);export{c as __pageData,b as default};
